function iniciarMenuMobile(){const e=document.getElementById("navToggle"),n=document.getElementById("navLinks");!e||!n||(e.addEventListener("click",function(){e.classList.toggle("open"),n.classList.toggle("open");const t=n.classList.contains("open");e.setAttribute("aria-expanded",t)}),n.querySelectorAll("a").forEach(function(t){t.addEventListener("click",function(){e.classList.remove("open"),n.classList.remove("open"),e.setAttribute("aria-expanded",!1)})}),window.addEventListener("resize",function(){window.innerWidth>768&&(e.classList.remove("open"),n.classList.remove("open"),e.setAttribute("aria-expanded",!1))}))}
